import { MeshStandardNodeMaterial } from 'three/webgpu';
import { texture, mul } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;

  // Root object
  const root = new Group();

  // Geometry – tessellated plane
  const geometry = new PlaneGeometry(7, 6, 64, 64);

  // Material – PBR machined‑metal base
  const material = new MeshStandardNodeMaterial();
  material.color = new Color('#0b0b10'); // surface
  material.metalness = 0.5;
  material.roughness = 0.5;

  // Load and apply colour texture
  let colourTex = null;
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    colourTex = tex;
    material.mapNode = texture(tex);
    material.needsUpdate = true;
  });

  // Load and apply depth (displacement) texture
  let depthTex = null;
  ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
    depthTex = tex;
    // displacement scale tuned for subtle depth
    material.displacementNode = mul(texture(tex), 0.08);
    material.needsUpdate = true;
  });

  // Mesh
  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Apply cinematic primitives from config
  const primitiveInstances = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const inst = ctx.primitives[prim.name](root, prim.params);
      primitiveInstances.push(inst);
    }
  }

  // Event handlers (hover, click)
  root.userData.handlers = {};

  root.userData.handlers.hover = () => {
    // rise‑in: subtle upward motion (0.15 scene units)
    gsap.to(root.position, { y: 0.15, duration: 0.3, ease: 'power3.out' });
  };

  root.userData.handlers.click = () => {
    ctx.emit('hub-home.select', {});
  };

  // Cleanup routine
  root.userData.cleanup = () => {
    // Dispose textures if they were loaded
    if (colourTex) colourTex.dispose();
    if (depthTex) depthTex.dispose();

    // Dispose geometry & material
    geometry.dispose();
    material.dispose();

    // Cleanup primitives
    for (const inst of primitiveInstances) {
      if (inst.cleanup) inst.cleanup();
    }

    // Kill any GSAP timelines created for this node
    gsap.globalTimeline.clear();
  };

  return root;
}
